Method.Source:
//TODO: Merge back to Metcash model when Metcash Price Eng model is removed
/// <summary>
/// Deleted event
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(METProfileCustTable), DataEventType::Deleted)]
public static void METProfileCustTable_onDeleted(Common sender, DataEventArgs e)
{
    METProfileCustTable metProfileCustTable =  sender as METProfileCustTable;
    
    METPriceChangeEventCustomer::metProcessTrackChange(metProfileCustTable.custTable());
}

    /// <summary>
    /// Inserted event
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [DataEventHandler(tableStr(METProfileCustTable), DataEventType::Inserted)]
    public static void METProfileCustTable_onInserted(Common sender, DataEventArgs e)
    {
        METProfileCustTable metProfileCustTable =  sender as METProfileCustTable;

        METPriceChangeEventCustomer::metProcessTrackChange(metProfileCustTable.custTable());
    }
